import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("b", 1, None)]) == 0.0


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0
    assert isinstance(conversion_rate([]), float)


def test_pooled_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 1, False), session("c", 1, None), session("d", 1, False)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_rate_without_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (4, 10), (10, 10)])
def test_trailing_window(days, expected):
    assert conversions_in_window([1, 2, 3, 4], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_converted_values_and_field_whitespace():
    assert parse_session_log([" a , 2 , 1 \n", " b , -1 , 0 ", " c , 3 , \t"]) == [
        session("a", 2, True), session("b", -1, False), session("c", 3, None)
    ]


def test_parse_skips_blank_whitespace_and_comment_lines():
    lines = ["", "\n", " \t\n", "# comment", " \t# not,a,session", "a,1,0"]
    assert parse_session_log(iter(lines)) == [session("a", 1, False)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-a-day,1", "a,1.5,0", "a,,1"])
def test_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", "a,1,1", " \t", bad_line])


def test_dedupe_duplicate_ids_keep_last_input_record():
    events = [
        session("a", 9, True),
        session("b", 2, True),
        session("a", 1, False),
        session("c", 1, None),
        session("b", 1, False),
    ]
    assert dedupe_sessions(events) == [events[2], events[4], events[3]]
    assert dedupe_sessions([]) == []


def test_daily_counts_fill_gaps_and_ignore_outside_range():
    events = [
        session("a", 0, True), session("b", 2, True), session("c", 2, True),
        session("d", 3, False), session("e", 3, None), session("f", 4, True),
        session("g", 6, True),
    ]
    assert daily_conversion_counts(events, 1, 5) == [0, 2, 0, 1, 0]
    assert daily_conversion_counts(events, 2, 2) == [2]
    assert daily_conversion_counts(events, 5, 1) == []
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]


def test_campaign_summary_uses_pooled_rate_calendar_days_and_nonempty_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 6, False)],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 20) == {"rate": 0.667, "recent": 2, "groups": 2}
    assert campaign_summary(groups, 0)["recent"] == 0


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_without_sessions(groups):
    assert campaign_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_exclude_empty_and_break_ties_by_name():
    groups = {
        "z": [session("a", 1, True)],
        "empty": [],
        "b": [session("b", 1, False)],
        "a": [session("c", 1, True)],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 2) == []
    assert top_converting_groups({}, 2) == []


def test_rates_by_group_are_sorted_and_empty_groups_have_none():
    groups = {
        "z": [],
        "b": [session("a", 1, True), session("b", 1, None)],
        "a": [session("c", 1, False)],
    }
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": 0.0, "b": 0.5, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize("counts, expected", [
    ([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5], 3),
    ([1, -1, 2], 1), ([1, 2, 3, 0, 1], 3), ([2, 1, 4], 3),
])
def test_longest_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_conversion_streak(counts) == expected
